//!
//! Parquet column statistics store the minimum and maximum values seen in a column. For
//! `BYTE_ARRAY` columns (strings and binary) these values can be arbitrarily large, which would
//! bloat the file metadata. To avoid this, we truncate the statistics to a bounded number of
//! bytes while keeping them valid bounds:
//! - the truncated *minimum* is a value that is `<=` the real minimum, and
//! - the truncated *maximum* is a value that is `>=` the real maximum.
//!
//! The truncation length is configurable through the
//! `POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN` environment variable. When it is unset the
//! default is [`DEFAULT_TRUNCATE_LEN`] bytes. When it is set to `0` truncation is disabled and the
//! exact statistics are kept.

use crate::parquet::schema::types::{
    PrimitiveConvertedType, PrimitiveLogicalType, PrimitiveType,
};

/// The default number of bytes statistics are truncated to when
/// `POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN` is not set.
pub(crate) const DEFAULT_TRUNCATE_LEN: usize = 64;

const ENV_TRUNCATE_LEN: &str = "POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN";

/// The configured statistics truncation length.
///
/// Returns `None` when truncation is disabled (the environment variable is set to `0`) and
/// `Some(len)` with the maximum number of bytes otherwise. The environment variable is read on
/// every call so that changes (e.g. from tests) take effect immediately.
pub(crate) fn statistics_truncate_length() -> Option<usize> {
    match std::env::var(ENV_TRUNCATE_LEN) {
        Ok(value) => match value.trim().parse::<usize>() {
            Ok(0) => None,
            Ok(len) => Some(len),
            // An unparseable value falls back to the default rather than failing the write.
            Err(_) => Some(DEFAULT_TRUNCATE_LEN),
        },
        Err(_) => Some(DEFAULT_TRUNCATE_LEN),
    }
}

/// Whether the given primitive type is a UTF-8 string column.
fn is_utf8(primitive_type: &PrimitiveType) -> bool {
    matches!(primitive_type.logical_type, Some(PrimitiveLogicalType::String))
        || matches!(primitive_type.converted_type, Some(PrimitiveConvertedType::Utf8))
}

/// Truncate the min/max statistics of a binary/string column in place, respecting the configured
/// truncation length. `min_value` and `max_value` are the raw (untruncated) statistics.
pub(crate) fn truncate_statistics(
    primitive_type: &PrimitiveType,
    min_value: Option<Vec<u8>>,
    max_value: Option<Vec<u8>>,
) -> (Option<Vec<u8>>, Option<Vec<u8>>) {
    let Some(length) = statistics_truncate_length() else {
        // Truncation disabled: keep the exact statistics.
        return (min_value, max_value);
    };

    let utf8 = is_utf8(primitive_type);
    let min_value = min_value.map(|v| truncate_min(v, utf8, length));
    let max_value = max_value.map(|v| truncate_max(v, utf8, length));
    (min_value, max_value)
}

/// Truncate a minimum statistic to at most `length` bytes.
fn truncate_min(value: Vec<u8>, utf8: bool, length: usize) -> Vec<u8> {
    // Values that already fit are left untouched.
    if value.len() <= length {
        return value;
    }

    if utf8 {
        if let Ok(s) = std::str::from_utf8(&value) {
            return truncate_utf8(s, length).as_bytes().to_vec();
        }
    }

    // Binary (or invalid UTF-8): truncate at the raw byte level.
    value[..length].to_vec()
}

/// Truncate a maximum statistic to at most `length` bytes, producing a valid upper bound.
fn truncate_max(value: Vec<u8>, utf8: bool, length: usize) -> Vec<u8> {
    // Values that already fit are left untouched.
    if value.len() <= length {
        return value;
    }

    if utf8 {
        if let Ok(s) = std::str::from_utf8(&value) {
            // Fall back to the exact value if we cannot produce a valid upper bound.
            return increment_utf8(truncate_utf8(s, length)).unwrap_or(value);
        }
    }

    increment_binary(&value, length).unwrap_or(value)
}

/// Return the longest prefix of `data` that is a valid UTF-8 string and fits within `length` bytes.
fn truncate_utf8(data: &str, length: usize) -> &str {
    let limit = length.min(data.len());
    // Find the largest byte index `<= limit` that lies on a character boundary. This avoids
    // splitting a multi-byte UTF-8 character.
    let split = (0..=limit)
        .rev()
        .find(|&idx| data.is_char_boundary(idx))
        .unwrap_or(0);
    &data[..split]
}

/// Increment a UTF-8 string to produce the smallest valid upper bound that keeps each character's
/// byte length unchanged. Returns `None` if no character can be incremented (e.g. the value only
/// contains the largest code points).
fn increment_utf8(data: &str) -> Option<Vec<u8>> {
    for (idx, original) in data.char_indices().rev() {
        let original_len = original.len_utf8();
        if let Some(next) = char::from_u32(original as u32 + 1) {
            // Do not allow increasing the byte width of the character.
            if next.len_utf8() == original_len {
                let mut result = data.as_bytes()[..idx + original_len].to_vec();
                next.encode_utf8(&mut result[idx..]);
                return Some(result);
            }
        }
    }
    None
}

/// Produce a valid upper bound for a binary value truncated to `length` bytes.
///
/// The value is first truncated to at most `length` bytes and the last non-`0xFF` byte is
/// incremented (dropping any trailing bytes). If every byte within the limit is `0xFF`, the search
/// continues beyond the limit to find the first non-`0xFF` byte, which is then incremented.
/// Returns `None` when the entire value consists of `0xFF` bytes and hence has no upper bound.
fn increment_binary(data: &[u8], length: usize) -> Option<Vec<u8>> {
    let limit = length.min(data.len());

    // Find the right-most non-`0xFF` byte within the limit and increment it.
    if let Some(pos) = data[..limit].iter().rposition(|&b| b != 0xFF) {
        let mut result = data[..=pos].to_vec();
        result[pos] += 1;
        return Some(result);
    }

    // All bytes within the limit are `0xFF`: search beyond the limit for the first non-`0xFF` byte.
    if let Some(offset) = data[limit..].iter().position(|&b| b != 0xFF) {
        let pos = limit + offset;
        let mut result = data[..=pos].to_vec();
        result[pos] += 1;
        return Some(result);
    }

    // The value is entirely `0xFF`; no upper bound exists.
    None
}
